# Let me try a different hypothesis:
# Only rows 1-3 and 11-13 get crosses, but ALL columns 2, 7, 11, 16

output = [[0]*18 for _ in range(16)]

# Vertical lines
for row in range(16):
    for col in [2, 7, 11, 16]:
        output[row][col] = 2

# Crosses only at rows 1-3 and 11-13 (centered at row 2 and row 12)
cross_rows = [2, 12]
cross_cols = [2, 7, 11, 16]

for cr in cross_rows:
    for cc in cross_cols:
        output[cr][cc] = 2
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                row, col = cr + dr, cc + dc
                if 0 <= row < 16 and 0 <= col < 18:
                    output[row][col] = 3

for row in output:
    print(row)

import json
print(json.dumps({"action": "submit", "grid": output}))

